        new Quote { Id = "https://pt.wikiquote.org/wiki/Lin_Yutang", Text = "A vida social só pode existir na base de uma certa dose de mentiras refinadas e de que ninguém diga exatamente o que pensa.", Author = "Lin Yutang" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Bob_Saget", Text = "Inteligência afiada, esperta, gentil, hilária, sincera e tão cheia de amor.", Author = "Bob Saget" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Jes%C3%BAs_Murgui_Soriano", Text = "Quando os pobres e os mais fracos estejam no centro de nosso pensamento se gerará uma mudança na sociedade.", Author = "Jesús Murgui Soriano" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Gabriel_Narciso_Escobar_Ayala", Text = "Uma característica do povo paraguaio é resistir e sofrer, mas não se pode mais tolerar esta situação, as pessoas desta parte do país merecem uma vida melhor.", Author = "Gabriel Narciso Escobar Ayala" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/C%C3%A9lestin_Freinet", Text = "A democracia de amanhã se prepara na democracia da escola.", Author = "Célestin Freinet" },
        new Quote { Id = "https://pt.wikiquote.org/wiki/Efraim_Sneh", Text = "Ficaremos por cima porque somos mais fortes.", Author = "Efraim Sneh" },
